def market_atmosphere(busy=False, time_of_day="afternoon"):
    if busy:
        market_atmosphere_string = "The air is thick with the scent of fresh produce and spices. Vendors call out prices and offers to countless shoppers. Crowds weave their way through the pink and green stalls, some pushing carts, some balancing baskets on their heads. It's a vibrant, chaotic scene where every person has a role in the colourful stream of life. A cross-section of society comes together here, each shopper driven by their own unique set of needs and desires."
    else:
        market_atmosphere_string = "A tranquil bustle fills the air as the morning sun paints the market in hues of orange and gold. Fresh produce vendors have set up their stalls and customers wander with baskets, stopping to inspect fruits, vegetables, and flowers. Passersby exchange greetings with a smile, and the occasional song pierces the air. There's a sense of community here, where people come together to enjoy the vibrancy of a market day, content in the simple pleasures of life."
    return market_atmosphere_string

